    async function checkForUpdate(options={}){const status=$('#version-status'),button=$('#check-update');if(!status||!button)return null;button.disabled=true;if(!options.silent)status.textContent='正在检查 GitHub…';try{let remoteText='',lastError=null;for(const source of versionSources){try{const response=await fetch(`${source}?t=${Date.now()}`,{cache:'no-store',headers:{Accept:'text/plain'}});if(!response.ok)throw new Error(`HTTP ${response.status}`);remoteText=await response.text();if(remoteText)break}catch(error){lastError=error}}if(!remoteText)throw lastError||new Error('无法读取远程版本');const match=remoteText.match(/version:\s*['"]([^'"]+)['"]/),remoteVersion=match?.[1],localVersion=release?.version;if(!remoteVersion||!localVersion)throw new Error('版本格式无法识别');const comparison=compareVersions(remoteVersion,localVersion);if(comparison===null)throw new Error('版本号不是有效的语义化版本');if(comparison>0){setUpdateAvailable(remoteVersion);status.textContent=`发现新版本 v${remoteVersion}`;notice(`发现新版本 v${remoteVersion}，可在设置中升级`)}else if(comparison<0){setUpdateAvailable('');status.textContent=`本地 v${localVersion} 高于远程 v${remoteVersion}`;if(!options.silent)notice('当前部署版本高于 GitHub 公开版本')}else{setUpdateAvailable('');status.textContent='已是最新版本';if(!options.silent)notice('当前已经是最新版本')}return {remoteVersion,comparison}}catch(error){console.warn('GitHub 版本检查失败：',error);if(!options.silent){status.textContent='检查失败，请稍后重试';notice('暂时无法读取 GitHub 版本信息')}return null}finally{button.disabled=false}}
