    const deviceGroups={light:['灯光','☼'],switch:['开关','⏻'],fan:['风扇','◉'],climate:['空调与温控','♨'],vacuum:['清洁设备','◔'],cover:['窗帘与遮阳','▤'],media_player:['媒体设备','♬'],lock:['门锁','⌑'],input_boolean:['虚拟开关','◌'],button:['按钮','●'],input_button:['按钮','●'],script:['脚本','▷'],automation:['自动化','↻'],siren:['警报器','!'],humidifier:['加湿器','≈'],water_heater:['热水器','♨']};
