    const WMO={0:['☀','晴'],1:['🌤','大致晴朗'],2:['⛅','多云'],3:['☁','阴'],45:['🌫','雾'],48:['🌫','雾凇'],51:['🌦','小毛雨'],53:['🌦','毛雨'],55:['🌧','大毛雨'],61:['🌦','小雨'],63:['🌧','中雨'],65:['🌧','大雨'],66:['🌧','冻雨'],67:['🌧','冻雨'],71:['🌨','小雪'],73:['🌨','中雪'],75:['❄','大雪'],77:['🌨','雪粒'],80:['🌦','阵雨'],81:['🌧','强阵雨'],82:['⛈','暴雨'],85:['🌨','阵雪'],86:['❄','阵雪'],95:['⛈','雷雨'],96:['⛈','雷雨伴冰雹'],99:['⛈','雷雨伴冰雹']};
    function syncWeatherSettings(){$('#weather-city').value=localStorage.getItem(weatherCityKey)||''}
    function renderWeather(cached){const {city,wx}=cached,[icon,desc]=WMO[wx.current?.weather_code]||['◌','未知'],cur=wx.current||{},daily=wx.daily||{time:[],weather_code:[],temperature_2m_min:[],temperature_2m_max:[]};$('#weather-status').textContent=city;$('#weather-body').innerHTML=`<div class="weather-now"><span class="weather-icon">${icon}</span><div class="weather-main"><b>${cur.temperature_2m??'--'}°C</b><small>${desc} · 体感 ${cur.apparent_temperature??'--'}°C</small></div><div class="weather-side"><small>湿度 ${cur.relative_humidity_2m??'--'}%</small></div></div><div class="weather-days">${(daily.time||[]).slice(1,4).map((t,i)=>{const [di,dd]=WMO[daily.weather_code?.[i+1]]||['◌','—'];const wd='日一二三四五六'[new Date(t+'T00:00:00').getDay()];return `<div class="weather-day"><span>${di}</span><small>周${wd}</small><b>${dd}</b><small>${Math.round(daily.temperature_2m_min[i+1]??0)}° / ${Math.round(daily.temperature_2m_max[i+1]??0)}°</small></div>`}).join('')}</div>`;weatherSummary=`${city}当前${desc}，${cur.temperature_2m}°C（体感 ${cur.apparent_temperature}°C，湿度 ${cur.relative_humidity_2m}%），未来三天 ${(daily.time||[]).slice(1,4).map((t,i)=>`${WMO[daily.weather_code?.[i+1]]?.[1]||'未知'}${Math.round(daily.temperature_2m_max[i+1]??0)}°`).join('、')}`}
    async function fetchWeather(force=false){const city=(localStorage.getItem(weatherCityKey)||'').trim();if(!city){$('#weather-status').textContent='待配置城市';$('#weather-body').innerHTML='<div class="empty-picker">在设置中填写城市后，展示当前天气与三日预报（Open-Meteo 免费开放接口，无需注册）。</div>';weatherSummary='';return}let cached=null;try{cached=JSON.parse(sessionStorage.getItem(weatherCacheKey)||'null')}catch(err){sessionStorage.removeItem(weatherCacheKey)}if(!force&&cached&&cached.city===city&&Date.now()-cached.at<30*60*1000){renderWeather(cached);return}$('#weather-status').textContent='正在获取 '+city+'…';try{const geo=await (await fetch(`https://geocoding-api.open-meteo.com/v1/search?name=${encodeURIComponent(city)}&count=1&language=zh&format=json`)).json();const loc=geo.results?.[0];if(!loc)throw new Error(`找不到城市「${city}」，请换个写法试试`);const wx=await (await fetch(`https://api.open-meteo.com/v1/forecast?latitude=${loc.latitude}&longitude=${loc.longitude}&current=temperature_2m,relative_humidity_2m,apparent_temperature,weather_code&daily=weather_code,temperature_2m_max,temperature_2m_min&timezone=auto&forecast_days=4`)).json();const payload={at:Date.now(),city:loc.name,wx};sessionStorage.setItem(weatherCacheKey,JSON.stringify(payload));renderWeather(payload)}catch(err){$('#weather-status').textContent='获取失败';$('#weather-body').innerHTML=`<div class="empty-picker">${escapeHtml(err.message==='Failed to fetch'?'无法连接 Open-Meteo，请检查网络后重试':err.message)}</div>`}}
    $('#weather-form').onsubmit=e=>{e.preventDefault();const city=$('#weather-city').value.trim().slice(0,24);if(!city){notice('请输入城市名称');return}localStorage.setItem(weatherCityKey,city);sessionStorage.removeItem(weatherCacheKey);notice(`天气城市已保存为「${city}」`);fetchWeather(true)};

    /* ===== AI 助手（OpenAI 兼容接口，可自配地址 / Key / 模型） ===== */
    const aiConfigKey='life-hub-ai-config';
    let aiHistory=[];
    function aiConfig(){try{const cfg=JSON.parse(localStorage.getItem(aiConfigKey)||'null');return cfg&&cfg.baseUrl&&cfg.apiKey&&cfg.model?cfg:null}catch(err){localStorage.removeItem(aiConfigKey);return null}}
    function updateAiLabel(){const cfg=aiConfig();$('#ai-model-label').textContent=cfg?.model||'未配置模型';$('#ai-dot').classList.toggle('ok',Boolean(cfg))}
    function syncAiSettings(){const raw=(()=>{try{return JSON.parse(localStorage.getItem(aiConfigKey)||'null')||{}}catch(err){return {}}})(),sel=$('#ai-model');$('#ai-base').value=raw.baseUrl||'';$('#ai-key').value=raw.apiKey||'';if(raw.model&&!sel.querySelector(`option[value="${raw.model}"]`))sel.insertAdjacentHTML('beforeend',`<option value="${escapeHtml(raw.model)}">${escapeHtml(raw.model)}</option>`);sel.value=raw.model||'';updateAiLabel()}
    function openAiPanel(){$('#ai-panel').classList.add('open');$('#ai-panel').setAttribute('aria-hidden','false');if(!aiHistory.length)renderAiMessages();$('#ai-question').focus()}
    function closeAiPanel(){$('#ai-panel').classList.remove('open');$('#ai-panel').setAttribute('aria-hidden','true')}
    function collectDashboardContext(){const d=new Date(),lines=[`现在是 ${d.toLocaleString('zh-CN',{hour12:false})}（${$('#today').textContent}），用户称呼 ${displayName()}。`];lines.push(`家庭环境：室内 ${$('#temperature').textContent}°C；${$('#environment').textContent}；连接状态 ${$('#ha-status').textContent}。`);if(weatherSummary)lines.push(`天气：${weatherSummary}。`);const onDevices=latestStates.filter(s=>canControl(s)&&isActive(s)).slice(0,10).map(s=>label(s));if(latestStates.length)lines.push(`Home Assistant：${latestStates.length} 个实体、${registry.areas.length} 个区域；当前开启：${onDevices.length?onDevices.join('、'):'无'}。`);const agenda=[...($('#agenda-list')?.querySelectorAll('.agenda-row')||[])].map(r=>r.textContent.replace(/\s+/g,' ').trim()).slice(0,5);if(agenda.length)lines.push(`今日安排：${agenda.join('；')}。`);const cds=countdowns().map(i=>({name:i.name,days:countdownDays(i)})).filter(i=>i.days!==null);if(cds.length)lines.push(`纪念日：${cds.map(i=>`${i.name}${i.days===0?'就是今天':`还有 ${i.days} 天`}`).join('、')}。`);return lines.join('\n')}
    function renderAiMessages(state){const box=$('#ai-messages');if(!aiHistory.length){box.innerHTML=`<div class="ai-empty"><div class="ai-empty-icon">✦</div><p>我可以读取看板数据与你对话。配置好 AI 后，问问我「家里现在多少度」「总结一下今天的安排」。</p><div class="ai-hints"><button class="ai-hint" type="button">家里现在什么情况？</button><button class="ai-hint" type="button">总结一下我今天的安排</button><button class="ai-hint" type="button">最近有什么值得纪念的日子？</button></div></div>`;box.querySelectorAll('.ai-hint').forEach(btn=>btn.onclick=()=>{$('#ai-question').value=btn.textContent.trim();$('#ai-form').requestSubmit()});return}box.innerHTML=aiHistory.map(m=>`<div class="ai-msg ${m.role==='user'?'user':'bot'}">${escapeHtml(m.content)}</div>`).join('')+(state==='thinking'?'<div class="ai-msg bot thinking">正在思考…</div>':'');box.scrollTop=box.scrollHeight}
    async function sendAiMessage(text){const cfg=aiConfig();if(!cfg){notice('请先在设置中配置 AI 助手');closeAiPanel();setView('settings');return}aiHistory.push({role:'user',content:text});renderAiMessages('thinking');try{const r=await fetch(cfg.baseUrl+'/chat/completions',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+cfg.apiKey},body:JSON.stringify({model:cfg.model,messages:[{role:'system',content:'你是"生活中枢"个人看板的内置 AI 助手，用简洁的中文回答。以下是看板的实时数据，回答时优先依据这些数据：\n'+collectDashboardContext()+'\n如果用户想控制设备，引导其在看板的快捷控制或 Home Assistant 区域卡片中操作。'},...aiHistory.slice(-20)],temperature:.6})});if(!r.ok)throw new Error(`接口返回 HTTP ${r.status}`);const data=await r.json(),reply=data.choices?.[0]?.message?.content?.trim();if(!reply)throw new Error('模型没有返回内容');aiHistory.push({role:'assistant',content:reply});renderAiMessages()}catch(err){aiHistory.pop();renderAiMessages();notice('AI 请求失败：'+(err.message==='Failed to fetch'?'无法连接接口，请检查地址与 CORS 设置':err.message))}}
    $('#ai-open').onclick=e=>{e.stopPropagation();openAiPanel()};
    $('#ai-close').onclick=closeAiPanel;
    $('#ai-form').onsubmit=e=>{e.preventDefault();const text=$('#ai-question').value.trim();if(!text)return;$('#ai-question').value='';sendAiMessage(text)};
    $('#ai-fetch-models').onclick=async()=>{const base=$('#ai-base').value.trim().replace(/\/+$/,''),key=$('#ai-key').value.trim(),status=$('#ai-config-status');if(!base||!key){status.textContent='请先填写接口地址和 API Key';return}if(!/^https?:\/\//.test(base)){status.textContent='接口地址需以 http(s):// 开头';return}status.textContent='正在拉取模型列表…';try{const r=await fetch(base+'/models',{headers:{Authorization:'Bearer '+key}});if(!r.ok)throw new Error(`HTTP ${r.status}`);const data=await r.json(),ids=(Array.isArray(data.data)?data.data:[]).map(m=>m&&m.id).filter(Boolean);if(!ids.length)throw new Error('接口未返回任何模型');const sel=$('#ai-model'),current=sel.value;sel.innerHTML=ids.map(id=>`<option value="${escapeHtml(id)}">${escapeHtml(id)}</option>`).join('');if(ids.includes(current))sel.value=current;status.textContent=`已获取 ${ids.length} 个模型，请选择后保存`}catch(err){status.textContent='拉取失败：'+(err.message==='Failed to fetch'?'无法连接接口，请检查地址与 CORS':err.message)}};
    $('#ai-config-form').onsubmit=e=>{e.preventDefault();const baseUrl=$('#ai-base').value.trim().replace(/\/+$/,''),apiKey=$('#ai-key').value.trim(),model=$('#ai-model').value,status=$('#ai-config-status');if(!/^https?:\/\//.test(baseUrl)){status.textContent='接口地址需以 http(s):// 开头';return}if(!apiKey){status.textContent='请填写 API Key';return}if(!model){status.textContent='请先拉取并选择模型';return}try{localStorage.setItem(aiConfigKey,JSON.stringify({baseUrl,apiKey,model}))}catch(err){status.textContent='浏览器阻止了保存';return}updateAiLabel();status.textContent='AI 配置已保存';notice('AI 助手配置已保存')};

    renderCountdowns();
    renderAiMessages();
    fetchWeather();
    setInterval(renderCountdowns,60*60*1000);
    setInterval(fetchWeather,30*60*1000);
